windows.precondition:
DO $g026_membership_precondition$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_catalog.pg_auth_members AS membership JOIN pg_catalog.pg_roles AS member_role ON member_role.oid = membership.member JOIN pg_catalog.pg_roles AS role_role ON role_role.oid = membership.roleid WHERE member_role.rolname = 'postgres' AND role_role.rolname = 'privacy_workflow_owner') THEN
    RAISE EXCEPTION 'privacy_workflow_owner replay membership already exists';
  END IF;
END;
$g026_membership_precondition$;

